<script setup>
import { ref } from 'vue'
import { useToast } from 'primevue/usetoast'
import { useConfirm } from 'primevue/useconfirm'
import {
  createGlossaryitem,
  deleteGlossaryitem,
  getGlossaryitemlist,
  updateGlossaryitem,
  createGlossaryWord,
  getGlossaryWordlist,
  indexGlossaryWord,
  updateGlossaryWord,
  deleteGlossaryWord,
  useGlossaryItem
} from '@/services/translate'
// 新增语言选项
const languageOptions = ref([
  { label: '中文', value: 'zh' },
  { label: '英文', value: 'en' },
  { label: '日文', value: 'ja' },
  { label: '韩语', value: 'ko' },
  { label: '法语', value: 'fr' }
])

// 新增源语言和目标语言配置
const sourceLang = ref(localStorage.getItem('sourceLang') || 'zh')
const targetLang = ref(localStorage.getItem('targetLang') || 'en')
const confirm = useConfirm()

defineProps({
  visible: Boolean
})

// const termGroups = ref(JSON.parse(localStorage.getItem('termGroups') || '[{"name":"默认术语表","domain":"通用","terms":[]}]'))
const termGroups = ref([])
const wordGroups = ref([])
const selectedGroupIndex = ref(0)
const activeGroupId = ref(null)
const newGroupDialog = ref(false)
const newGroupName = ref('')
const newGroupDomain = ref('通用')
const searchKeyword = ref('')
const filteredTerms = ref([])
const count = ref(0)

const deleteGroup = async (event) => {
  try {
    confirm.require({
      target: event.currentTarget,
      message: '确定要删除这个术语表吗？',
      icon: 'pi pi-exclamation-triangle',
      accept: async () => {
        const currentGroup = termGroups.value[selectedGroupIndex.value]
        const res = await deleteGlossaryitem(currentGroup.id)
        if (res.resData === 'success') {
          toast.add({
            severity: 'success',
            summary: '删除成功',
            detail: '术语表已删除',
            life: 3000
          })
          count.value += 1
          selectedGroupIndex.value = 0
        }
      }
    })
  } catch (error) {
    toast.add({
      severity: 'error',
      summary: '删除失败',
      detail: error.message || '删除操作异常',
      life: 3000
    })
  }
}

const filterTerms = () => {
  if (searchKeyword.value) {
    indexGlossaryWord({
      id: termGroups.value[selectedGroupIndex.value].id,
      base_language: searchKeyword.value
    }).then((res) => {
      filteredTerms.value = res.resData
    })
  }
}
const newSource = ref('')
const newTarget = ref('')
const editingIndex = ref(-1)

const toast = useToast()

const saveGlossaryitem = async () => {
  try {
    const res = await createGlossaryitem({
      name: newGroupName.value,
      field: newGroupDomain.value
    })
    count.value += 1
    if (res.resData === 'success') {
      toast.add({
        severity: 'success',
        summary: '操作成功',
        detail: '术语表已保存',
        life: 3000
      })
    } else {
      toast.add({
        severity: 'error',
        summary: '操作失败',
        detail: '保存术语表时发生错误',
        life: 3000
      })
    }
  } catch (error) {
    toast.add({
      severity: 'error',
      summary: '请求异常',
      detail: error.message || '网络连接异常',
      life: 3000
    })
  }
}
watch(
  () => count.value,
  async () => {
    try {
      const res = await getGlossaryitemlist()
      termGroups.value = res.resData
    } catch (error) {
      console.error('获取术语表列表失败:', error)
    }
  }
)
watch(
  () => selectedGroupIndex.value,
  async () => {
    try {
      const res = await getGlossaryWordlist(termGroups.value[selectedGroupIndex.value].id)
      wordGroups.value = res.resData
    } catch (error) {
      console.error('获取列表失败:', error)
    }
  }
)
watch(
  () => searchKeyword.value,
  () => {
    filterTerms()
  }
)

const addTerm = async () => {
  if (newSource.value && newTarget.value) {
    try {
      const saveRes = await createGlossaryWord({
        glossary_id: termGroups.value[selectedGroupIndex.value].id,
        base_language: newSource.value,
        target_language: newTarget.value,
        base_lang: sourceLang.value,
        target_lang: targetLang.value
      })

      if (saveRes.resData === 'success') {
        toast.add({
          severity: 'success',
          summary: '操作成功',
          detail: '已保存',
          life: 3000
        })

        // 获取最新词汇列表
        const wordsRes = await getGlossaryWordlist(termGroups.value[selectedGroupIndex.value].id)
        wordGroups.value = wordsRes.resData

        // 更新术语表词汇量
        termGroups.value[selectedGroupIndex.value].total_num_words = wordGroups.value.length

        // 更新后端术语表数据
        await updateGlossaryitem({
          id: termGroups.value[selectedGroupIndex.value].id,
          total_num_words: wordGroups.value.length
        })

        // 触发术语表列表刷新
        count.value += 1

        // 清空输入框
        newSource.value = ''
        newTarget.value = ''
      } else {
        toast.add({
          severity: 'error',
          summary: '操作失败',
          detail: '保存时发生错误',
          life: 3000
        })
      }
    } catch (error) {
      toast.add({
        severity: 'error',
        summary: '请求异常',
        detail: error.message || '网络连接异常',
        life: 3000
      })
    }
  }
}

const editTerm = (index) => {
  editingIndex.value = index
  newSource.value = wordGroups.value[index].base_language
  newTarget.value = wordGroups.value[index].target_language
  sourceLang.value = wordGroups.value[index].base_lang
  targetLang.value = wordGroups.value[index].target_lang
}

const updateTerm = async () => {
  if (editingIndex.value >= 0) {
    try {
      const updateRes = await updateGlossaryWord({
        base_language: newSource.value,
        target_language: newTarget.value,
        base_lang: sourceLang.value,
        target_lang: targetLang.value,
        id: wordGroups.value[editingIndex.value].id
      })

      if (updateRes.resData === 'success') {
        toast.add({
          severity: 'success',
          summary: '操作成功',
          detail: '术语已更新',
          life: 3000
        })

        // 获取最新词汇列表
        const wordsRes = await getGlossaryWordlist(termGroups.value[selectedGroupIndex.value].id)
        wordGroups.value = wordsRes.resData

        // 更新术语表词汇量
        termGroups.value[selectedGroupIndex.value].total_num_words = wordGroups.value.length

        // 更新后端术语表数据
        await updateGlossaryitem({
          id: termGroups.value[selectedGroupIndex.value].id,
          total_num_words: wordGroups.value.length
        })

        // 触发术语表列表刷新
        count.value += 1
      } else {
        toast.add({
          severity: 'error',
          summary: '操作失败',
          detail: '更新时发生错误',
          life: 3000
        })
      }

      // 重置编辑状态
      editingIndex.value = -1
      newSource.value = ''
      newTarget.value = ''
    } catch (error) {
      toast.add({
        severity: 'error',
        summary: '请求异常',
        detail: error.message || '网络连接异常',
        life: 3000
      })
    }
  }
}

const deleteTerm = async (index) => {
  if (index >= 0) {
    try {
      const deleteRes = await deleteGlossaryWord(wordGroups.value[index].id)

      if (deleteRes.resData === 'success') {
        toast.add({
          severity: 'success',
          summary: '操作成功',
          detail: '术语已删除',
          life: 3000
        })

        // 获取最新词汇列表
        const wordsRes = await getGlossaryWordlist(termGroups.value[selectedGroupIndex.value].id)
        wordGroups.value = wordsRes.resData

        // 更新术语表词汇量
        termGroups.value[selectedGroupIndex.value].total_num_words = wordGroups.value.length

        // 更新后端术语表数据
        await updateGlossaryitem({
          id: termGroups.value[selectedGroupIndex.value].id,
          total_num_words: wordGroups.value.length
        })

        // 触发术语表列表刷新
        count.value += 1
      } else {
        toast.add({
          severity: 'error',
          summary: '操作失败',
          detail: '删除时发生错误',
          life: 3000
        })
      }
    } catch (error) {
      toast.add({
        severity: 'error',
        summary: '请求异常',
        detail: error.message || '网络连接异常',
        life: 3000
      })
    }
  }
}

onMounted(async () => {
  getGlossaryitemlist().then(async (res) => {
    termGroups.value = res.resData

    if (termGroups.value.length === 0) {
      await createGlossaryitem({
        name: '默认术语表',
        field: '通用'
      })
      const newRes = await getGlossaryitemlist()
      termGroups.value = newRes.resData
    } else {
      const res = await getGlossaryWordlist(termGroups.value[selectedGroupIndex.value].id)
      wordGroups.value = res.resData
    }
  })
})
</script>

<template>
  <Dialog :visible="newGroupDialog" @update:visible="(val) => (newGroupDialog = val)" header="新建术语表" :style="{ width: '500px' }">
    <div class="p-fluid">
      <div class="field">
        <label>术语表名称</label>
        <InputText v-model="newGroupName" />
      </div>
      <div class="field">
        <label>应用领域</label>
        <InputText v-model="newGroupDomain" />
      </div>
      <Button
        label="创建"
        icon="pi pi-check"
        class="p-button-sm"
        @click="
          () => {
            saveGlossaryitem()
            newGroupDialog = false
          }
        "
      />
    </div>
  </Dialog>

  <Dialog :visible="visible" @update:visible="$emit('update:visible', $event)" :style="{ width: '800px' }">
    <template #header>
      <div class="flex justify-content-between align-items-center">
        <span>术语表管理</span>
      </div>
    </template>
    <div class="term-management">
      <!-- 搜索区域保持原有布局 -->
      <div class="flex gap-4 mb-4">
        <div class="flex-1">
          <label class="block text-sm font-medium mb-2">搜索关键词</label>
          <div class="flex gap-2">
            <InputText v-model="searchKeyword" placeholder="输入关键词过滤" class="flex-1" />
            <Button label="查询" icon="pi pi-search" class="p-button-sm" @click="filterTerms" />
          </div>
        </div>
      </div>

      <!-- 术语输入区域添加操作按钮 -->
      <div class="flex flex-col gap-4 mb-4">
        <div class="flex gap-2 items-center">
          <div class="w-24">
            <Dropdown
              v-model="sourceLang"
              :options="languageOptions"
              optionLabel="label"
              optionValue="value"
              class="p-inputtext-sm w-full"
              placeholder="源语言"
            />
          </div>
          <div class="flex-1">
            <InputText v-model="newSource" class="w-full" placeholder="源术语" />
          </div>
        </div>

        <div class="flex gap-2 items-center">
          <div class="w-24">
            <Dropdown
              v-model="targetLang"
              :options="languageOptions"
              optionLabel="label"
              optionValue="value"
              class="p-inputtext-sm w-full"
              placeholder="目标语言"
            />
          </div>
          <div class="flex-1">
            <InputText v-model="newTarget" class="w-full" placeholder="目标术语" />
          </div>
        </div>
      </div>

      <div class="flex gap-2 mb-4">
        <Button v-if="editingIndex === -1" label="新增" icon="pi pi-plus" class="p-button-sm" @click="addTerm" />
        <Button v-else label="更新" icon="pi pi-check" class="p-button-sm p-button-success" @click="updateTerm" />
      </div>

      <div class="flex flex-col gap-4 mb-4">
        <div class="flex justify-content-between align-items-center">
          <div class="flex gap-2 align-items-center">
            <Button
              :label="activeGroupId === termGroups[selectedGroupIndex]?.id ? '已启用' : '启用术语表'"
              :class="[
                'p-button-sm',
                {
                  'p-button-success': activeGroupId === termGroups[selectedGroupIndex]?.id,
                  'p-button-secondary': activeGroupId !== termGroups[selectedGroupIndex]?.id
                }
              ]"
              @click="
                async () => {
                  const newState = activeGroupId !== termGroups[selectedGroupIndex]?.id
                  const action = newState ? 'open' : 'close'
                  const currentId = termGroups[selectedGroupIndex]?.id

                  try {
                    const res = await useGlossaryItem({
                      id: currentId,
                      state: action
                    })

                    if (res.resData === 'success') {
                      activeGroupId = newState ? currentId : null
                      toast.add({
                        severity: 'success',
                        summary: '操作成功',
                        detail: `术语表已${action === 'open' ? '启用' : '关闭'}`,
                        life: 3000
                      })
                    }
                  } catch (error) {
                    toast.add({
                      severity: 'error',
                      summary: '操作失败',
                      detail: error.message || '请求异常',
                      life: 3000
                    })
                  }
                }
              "
            />
            <span v-if="activeGroupId" class="text-color-secondary text-sm">
              当前启用：{{ termGroups.find((g) => g.id === activeGroupId)?.name }}
            </span>
            <Dropdown
              v-model="selectedGroupIndex"
              :options="termGroups.map((g, i) => ({ label: g.name, value: i }))"
              optionLabel="label"
              optionValue="value"
              class="w-48"
            />
            <Button icon="pi pi-plus" label="新建术语库" class="p-button-sm p-button-outlined" @click="newGroupDialog = true" />
          </div>
        </div>
        <div class="flex align-items-center gap-4 h-8">
          <div class="flex align-items-center gap-0">
            当前领域：{{ termGroups[selectedGroupIndex]?.field }} 词汇量：{{ termGroups[selectedGroupIndex]?.total_num_words }}
          </div>
          <Button
            icon="pi pi-trash"
            class="p-button-sm p-button-danger p-button-text"
            @click="deleteGroup($event)"
            v-if="termGroups.length > 0"
          />
        </div>
        <ConfirmPopup />
      </div>

      <DataTable :value="filteredTerms.length > 0 && searchKeyword ? filteredTerms : wordGroups" class="p-datatable-sm" :rows="10">
        <Column header="所属术语表" style="width: 180px">
          <template #body="{ data }" v-if="filteredTerms.length > 0 && searchKeyword">
            {{ termGroups.find((g) => g.id === data.glossary_id)?.name }}
          </template>
          <template #body="" v-else>
            {{ termGroups[selectedGroupIndex]?.name }}
          </template>
        </Column>
        <Column header="源语言" style="width: 120px">
          <template #body="{ data }">
            {{ languageOptions.find((l) => l.value === data.base_lang)?.label || data.base_lang }}
          </template>
        </Column>
        <Column field="source" header="源术语" style="width: 120px">
          <template #body="{ data }">
            {{ languageOptions.find((l) => l.value === data.base_language)?.label || data.base_language }}
          </template>
        </Column>
        <Column header="目标语言" style="width: 120px">
          <template #body="{ data }">
            {{ languageOptions.find((l) => l.value === data.target_lang)?.label || data.target_lang }}
          </template>
        </Column>
        <Column field="target" header="目标术语" style="width: 120px">
          <template #body="{ data }">
            {{ languageOptions.find((l) => l.value === data.target_language)?.label || data.target_language }}
          </template>
        </Column>
        <Column header="操作" style="width: 120px">
          <template #body="{ index }">
            <Button icon="pi pi-pencil" class="p-button-text p-button-sm" @click="editTerm(index)" />
            <Button icon="pi pi-trash" class="p-button-text p-button-sm p-button-danger" @click="deleteTerm(index)" />
          </template>
        </Column>
      </DataTable>
    </div>
  </Dialog>
</template>

<style scoped>
.term-management {
  padding: 1rem;
}
</style>
