<script setup>
import { ref, watch, computed } from 'vue'
import Dialog from 'primevue/dialog'
import DualFilePreview from './DualFilePreview.vue'
import { saveAs } from 'file-saver'
import {
  getTranslateText,
  uploadFile,
  setbase_target_lang,
  getTranslatetextHistory,
  deleteTranslatetextHistory
} from '@/services/translate'
import useModelStore from '@/stores/models'
const ModelStore = useModelStore()

function initModel() {
  Promise.allSettled([ModelStore.getModelList(), ModelStore.getLoadedModel()])
}

initModel()

const globalLoading = ref(false)

async function loadModel(model) {
  globalLoading.value = true // 设置全局加载状态为 true，表示加载中
  const { id } = model
  try {
    // 加载模型
    await ModelStore.loadModel(model)

    // 等待模型加载完成
    await waitForModelReady()
  } catch (error) {
    console.error(`Failed to load model ${id}:`, error)
  } finally {
    globalLoading.value = false // 无论加载成功还是失败，都将全局加载状态设置为 false
  }
}

async function waitForModelReady() {
  // eslint-disable-next-line no-constant-condition
  while (true) {
    const status = await ModelStore.getModelLoadStatus()

    if (status === 12) {
      await ModelStore.getLoadedModel()
      break // 加载完成，退出循环
    }

    // 模型还在加载中，等待1秒后继续检查状态
    await new Promise((resolve) => setTimeout(resolve, 1000))
  }
}

const models = computed(() => ModelStore.modelList)
const selectedModel = computed({
  get: () => ModelStore.loadedModel?.id || '',
  set: async (val) => {
    await loadModel({ id: val })
  }
})

async function changePrecise({ value: precise }) {
  console.log('precise', precise)
  await loadModel({ id: ModelStore.loadedModel?.id, precise })
}

const languages = ref(
  [
    { code: 'zh', name: '中文' },
    { code: 'en', name: '英语' },
    { code: 'ja', name: '日语' },
    { code: 'ko', name: '韩语' },
    { code: 'fr', name: '法语' }
  ].filter((v, i, a) => a.findIndex((t) => t.code === v.code && t.name === v.name) === i)
)

const sourceLang = ref('zh')
const targetLang = ref('en')
const inputText = ref('')
const translatedText = ref('')
const isTranslating = ref(false)

const handleTranslate = async () => {
  try {
    isTranslating.value = true
    const res = await getTranslateText({
      text: inputText.value,
      source: sourceLang.value,
      target: targetLang.value
    })
    translatedText.value = res.resData
  } catch (error) {
    console.error('翻译失败:', error)
  } finally {
    isTranslating.value = false
  }
}

const swapLanguages = () => {
  const temp = sourceLang.value
  sourceLang.value = targetLang.value
  targetLang.value = temp
}

watch(
  () => targetLang.value,
  (newValue) => {
    setbase_target_lang({
      source: sourceLang.value,
      target: newValue
    })
  }
),
  { immediate: true }

watch(
  () => sourceLang.value,
  (newValue) => {
    setbase_target_lang({
      source: sourceLang.value,
      target: newValue
    })
  }
)

const debounceTimer = ref(null)
const showTermGlossary = ref(false)
const showPreviewDialog = ref(false)
const previewFileUrl = ref('')
const fileType = ref('')
const showHistoryDialog = ref(false)
const translationHistoryList = ref([])
const isHistoryLoading = ref(false)

const isUploading = ref(false)
const translationHistory = ref([])
const showHistory = ref(false)
const showFileHistory = ref(false)

const handleInput = () => {
  clearTimeout(debounceTimer.value)
  debounceTimer.value = setTimeout(() => {
    if (inputText.value.trim()) {
      handleTranslate()
    }
  }, 500)
}

//先上传
const handleFileUpload = async (e) => {
  try {
    isUploading.value = true
    const file = e.target.files[0]
    console.log('file:', file)
    // 调用后端接口上传文件并获取文件ID
    fileType.value = file.name.split('.').pop().toLowerCase()
    const formData = new FormData()
    formData.append('files', file)
    uploadFile(formData).then((res) => {
      previewFileUrl.value = res.resData
      showPreviewDialog.value = true
    })
    e.target.value = '' // 清空选择允许重复上传相同文件
  } catch (error) {
    console.error('文件上传失败:', error)
    alert('文件上传失败，请检查文件格式')
  } finally {
    isUploading.value = false
  }
}

const handleCopy = async () => {
  try {
    await navigator.clipboard.writeText(translatedText.value)
    alert('复制成功！')
  } catch (err) {
    console.error('复制失败:', err)
  }
}

setbase_target_lang({
  source: sourceLang.value,
  target: targetLang.value
})

onBeforeUnmount(() => {
  clearTimeout(debounceTimer.value)
})

// 获取翻译历史
const fetchTranslationHistory = async () => {
  showHistoryDialog.value = true
  try {
    isHistoryLoading.value = true
    const res = await getTranslatetextHistory()
    translationHistoryList.value = res.resData || []
  } catch (error) {
    console.error('获取翻译历史失败:', error)
  } finally {
    isHistoryLoading.value = false
  }
}

// 删除翻译历史记录
const deleteHistoryItem = async (id) => {
  try {
    await deleteTranslatetextHistory(id)
    // 删除成功后刷新列表
    await fetchTranslationHistory()
  } catch (error) {
    console.error('删除翻译历史失败:', error)
  }
}

// 导出翻译历史
const exportHistory = async () => {
  const markdownContent = translationHistoryList.value
    .map((item) => {
      const sourceLang = languages.value.find((lang) => lang.code === item.base_lang)?.name || item.base_lang
      const targetLang = languages.value.find((lang) => lang.code === item.target_lang)?.name || item.target_lang
      const time = formatTime(item.create_time)
      return `## 翻译记录 (${time})
- 源语言: ${sourceLang}
- 目标语言: ${targetLang}

### 原文
${item.origin_text}

### 译文
${item.transed_text}

---
`
    })
    .join('\n')

  const uint8arr = new TextEncoder().encode(markdownContent) // 编码为 Uint8Array
  const filename = `翻译历史_${new Date().toISOString().split('T')[0]}.md`

  try {
    const success = await window.pywebview.api.save_blob_file(filename, Array.from(uint8arr))
    if (!success) {
      console.warn('用户取消了保存翻译历史')
    }
  } catch (error) {
    console.error('保存翻译历史失败:', error)
  }
}

// 格式化时间
const formatTime = (time) => {
  return new Date(time).toLocaleString()
}
</script>
<template>
  <div class="translate-container h-full flex flex-col p-4">
    <div class="flex flex-col gap-4">
      <!-- 模型选择单独一行 -->
      <div class="w-full model_selector flex flex-row gap-4 items-center">
        <div class="flex-1">
          <Dropdown
            class="border-none font-semibold w-full"
            v-model="selectedModel"
            :options="models"
            optionLabel="name"
            optionValue="id"
            :placeholder="$t('lang.loadModelNeeded')"
          >
            <template #value="slotProps">
              <div v-if="slotProps.value" class="flex items-center gap-3">
                <img
                  :alt="slotProps.value.label"
                  class="w-6 h-6 rounded-full"
                  :src="models.find((item) => item.id === slotProps.value)?.model_pic"
                />
                <div class="font-bold text-slate-600">
                  {{ models.find((item) => item.id === slotProps.value)?.name }}
                </div>
              </div>
              <span v-else>
                {{ slotProps.placeholder }}
              </span>
            </template>
            <template #option="slotProps">
              <div class="flex align-items-center gap-3">
                <img class="w-6 h-6 rounded-full" :alt="slotProps.option.name" :src="slotProps.option.model_pic" />
                <div class="font-bold">{{ slotProps.option.name }}</div>
              </div>
            </template>
          </Dropdown>
        </div>
        <div class="flex-1">
          <Dropdown
            class="w-full"
            :options="ModelStore.loadedModel?.precise_option || []"
            @change="changePrecise"
            :model-value="ModelStore.loadedModel?.precise_load"
          />
        </div>
      </div>

      <!-- 语言选择水平排列 -->
      <div class="flex items-center gap-4 justify-between w-full flex-nowrap">
        <select v-model="sourceLang" class="lang-select flex-1 min-w-0">
          <option v-for="lang in languages" :key="lang.code" :value="lang.code">
            {{ lang.name }}
          </option>
        </select>
        <button @click="swapLanguages" class="swap-btn">
          <svg class="w-5 h-5 mx-2 p-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" />
          </svg>
        </button>
        <select v-model="targetLang" class="lang-select flex-1 min-w-0">
          <option v-for="lang in languages" :key="lang.code" :value="lang.code">
            {{ lang.name }}
          </option>
        </select>
        <button @click="showTermGlossary = true" class="translate-btn text-sm flex-shrink-0 min-w-32 whitespace-nowrap">术语表配置</button>
        <button @click="fetchTranslationHistory" class="translate-btn text-sm flex-shrink-0 min-w-32 whitespace-nowrap">翻译历史</button>
      </div>

      <!-- 添加翻译状态提示 -->
      <div v-if="isTranslating" class="translation-status">
        <div class="flex items-center gap-2 text-blue-500">
          <div class="animate-spin rounded-full h-4 w-4 border-b-2 border-blue-500"></div>
          <span>翻译中...</span>
        </div>
      </div>
    </div>

    <div class="flex-1 flex flex-col md:flex-row gap-0 min-h-0 mt-4 border border-gray-200 rounded-lg overflow-hidden">
      <div class="input-area flex-1 flex flex-col">
        <div class="h-10 bg-gray-50 flex items-center px-4 border-b border-gray-200">
          <label class="cursor-pointer text-blue-500 text-sm hover:text-blue-600">
            <input type="file" class="hidden" accept=".pdf,.docx,.txt" @change="handleFileUpload" />
            上传文档
          </label>
          <div class="ml-auto flex items-center gap-2">
            <button v-if="translationHistory.length" @click="showHistory = !showHistory" class="text-blue-500 text-sm hover:text-blue-600">
              {{ showHistory ? '隐藏历史' : '查看全部历史' }}
            </button>
            <button
              v-if="translationHistory.some((item) => item.isFile)"
              @click="showFileHistory = !showFileHistory"
              class="text-blue-500 text-sm hover:text-blue-600"
            >
              {{ showFileHistory ? '隐藏文件历史' : '查看文件历史' }}
            </button>
          </div>
        </div>
        <div class="relative flex-1">
          <textarea
            v-model="inputText"
            placeholder="输入要翻译的内容"
            class="w-full h-full p-4 resize-none focus:outline-none overflow-auto"
            @input="handleInput"
          ></textarea>
          <button @click="handleTranslate" class="translate-btn absolute bottom-4 right-4">立即翻译</button>
        </div>
        <div v-if="showHistory || showFileHistory" class="history-panel border-t border-gray-200">
          <div
            v-for="(item, index) in showFileHistory ? translationHistory.filter((item) => item.isFile) : translationHistory"
            :key="index"
            class="history-item"
          >
            <div class="text-sm text-gray-500">{{ item.timestamp }}</div>
            <div v-if="item.isFile" class="flex items-center gap-2">
              <span class="file-icon">📁</span>
              <span class="truncate">{{ item.fileName }}</span>
              <button @click="handleRetranslateFile(item)" class="ml-2 text-green-500 hover:text-green-600 text-sm">
                @click=" previewFileUrl = { left: item.filePath, right: item.filePath } showPreviewDialog = true " class="text-blue-500
                hover:text-blue-600 text-sm" > 预览
              </button>
              <button @click="handleRetranslateFile(item)" class="ml-2 text-green-500 hover:text-green-600 text-sm">重新翻译</button>
            </div>
            <template v-else>
              <div class="truncate">{{ item.source }}</div>
              <div class="text-gray-400">→</div>
              <div class="truncate">{{ item.target }}</div>
            </template>
          </div>
        </div>
      </div>

      <div class="divider w-px bg-gray-200"></div>

      <div class="result-area flex-1 flex flex-col">
        <div class="h-10 bg-gray-50 flex items-center px-4 border-b border-gray-200">
          <button @click="handleCopy" class="ml-auto flex items-center gap-1 text-sm text-gray-600 hover:text-gray-800">
            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path
                stroke-linecap="round"
                stroke-linejoin="round"
                stroke-width="2"
                d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"
              />
            </svg>
            复制
          </button>
        </div>
        <div class="flex-1 p-4 overflow-auto">
          <div v-if="isTranslating" class="flex items-center justify-center h-full">
            <div class="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
          </div>
          <div v-else class="translated-text whitespace-pre-wrap">{{ translatedText }}</div>
        </div>
      </div>
    </div>
  </div>
  <Dialog v-model:visible="showPreviewDialog" header="文件预览" :style="{ width: '90vw', height: '90vh' }">
    <DualFilePreview :fileName="previewFileUrl" :fileType="fileType" />
  </Dialog>

  <Dialog v-model:visible="showHistoryDialog" header="翻译历史" :style="{ width: '60vw' }" :modal="true">
    <div class="history-container">
      <div class="history-header flex items-center justify-between mb-4">
        <h3 class="text-lg font-semibold">翻译记录</h3>
        <div class="flex items-center gap-2">
          <button @click="exportHistory" class="export-btn p-2 rounded hover:bg-gray-100 text-green-500 hover:text-green-600">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path
                stroke-linecap="round"
                stroke-linejoin="round"
                stroke-width="2"
                d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"
              />
            </svg>
          </button>
          <button @click="fetchTranslationHistory" class="refresh-btn p-2 rounded hover:bg-gray-100">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path
                stroke-linecap="round"
                stroke-linejoin="round"
                stroke-width="2"
                d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
              />
            </svg>
          </button>
        </div>
      </div>
      <div class="history-list max-h-[60vh] overflow-auto">
        <div v-if="isHistoryLoading" class="flex justify-center items-center h-32">
          <div class="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
        </div>
        <div v-else-if="translationHistoryList.length === 0" class="text-center text-gray-500 py-8">暂无翻译历史记录</div>
        <div v-else class="space-y-4">
          <div v-for="(item, index) in translationHistoryList" :key="index" class="history-item p-4 border rounded-lg">
            <div class="flex justify-between text-sm text-gray-500 mb-2">
              <span>原始语言: {{ languages.find((lang) => lang.code === item.base_lang)?.name || item.base_lang }}</span>
              <span>目标语言: {{ languages.find((lang) => lang.code === item.target_lang)?.name || item.target_lang }}</span>
              <div class="flex items-center gap-2">
                <span>{{ formatTime(item.create_time) }}</span>
                <button @click="deleteHistoryItem(item.id)" class="delete-btn p-1 rounded hover:bg-red-50 text-red-500 hover:text-red-600">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path
                      stroke-linecap="round"
                      stroke-linejoin="round"
                      stroke-width="2"
                      d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                    />
                  </svg>
                </button>
              </div>
            </div>
            <div class="grid grid-cols-2 gap-4">
              <div class="original-text">
                <div class="text-sm text-gray-500 mb-1">原文</div>
                <div class="p-2 bg-gray-50 rounded">{{ item.origin_text }}</div>
              </div>
              <div class="translated-text">
                <div class="text-sm text-gray-500 mb-1">译文</div>
                <div class="p-2 bg-gray-50 rounded">{{ item.transed_text }}</div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </Dialog>

  <TermGlossary :visible="showTermGlossary" @update:visible="(val) => (showTermGlossary = val)" />
</template>

<script>
import TermGlossary from './TermGlossary.vue'
import Dropdown from 'primevue/dropdown'
</script>
<style scoped>
