  align-items: center;
}

/* 响应式调整 */
@media screen and (max-width: 768px) {
  .translate-container {
    padding: 0.5rem;
  }

  .lang-select {
    width: 24px;
    padding: 0.25rem;
  }

  .swap-btn,
  :global(.translate-btn),
  .file-action-btn,
  .history-btn,
  .copy-btn {
    height: 32px;
    padding: 0.375rem 0.625rem;
    font-size: 13px;
  }
  .button-group {
    gap: 0.375rem;
  }
}

.translation-status {
  @apply mt-2 text-sm;
  animation: fadeIn 0.3s ease-in-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
</style>
